// #f6e816402bc7433839ec2a6f — открытая вкладка участника после смены роли / блокировки (кейсы UA-004, UA-005)
// + #4cfd0ae49bece5d24e46d903 — старый токен заблокированного участника (UA-002, часть «блокировка»).
// Два окна одновременно: business (исполнитель) и РАСХОДНЫЙ участник бизнеса testim «spare» с ролью «מנהל/ת חשבון».
// ПРЕДУСЛОВИЯ:
//   - расходный участник (НЕ общие business/user): сессия .qa/auth/spare.json (аккаунт «spare» в accounts.json,
//     QA_USER_SPARE_EMAIL / QA_USER_SPARE_PASSWORD в accounts.env, затем npm run qa-login). Нет файла — тесты пропускаются.
//   - тест блокировки завершает сессию spare (выход на клиенте) → после него снова qa-login для spare;
//     поэтому он идёт только с QA_RUN_SESSION_KILL=1.
// Роль и статус spare восстанавливаются в конце каждого теста («הפיכה למנהל/ת חשבון», «ביטול חסימה»).
import * as fs from 'fs';
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { openWithApi } from '../support/api';
import { authFile, DATA_TABLES, readSession } from '../support/session';

test.describe.configure({ mode: 'serial' });

const HAS_SPARE = fs.existsSync(authFile('spare'));
const SPARE_EMAIL = HAS_SPARE ? readSession('spare').user.email : '';

const MANAGER = 'מנהל/ת חשבון';
const RECRUITER = 'מנהל/ת מגייס/ת';
const MANAGER_ONLY_LINKS = ['משתמשים והזמנות', 'הגדרות העסק'];

const spareRow = (business: Page) => business.getByRole('row').filter({ hasText: SPARE_EMAIL });

async function openUsers(business: Page) {
  await business.goto('/settings/users');
  await expect(spareRow(business)).toBeVisible();
}

async function setManager(business: Page) {
  const row = spareRow(business);
  const promote = row.getByRole('button', { name: `הפיכה ל${MANAGER}` });
  if (await promote.isVisible()) {
    await promote.click();
    await expect(row.getByRole('button', { name: `הפיכה ל${RECRUITER}` })).toBeVisible();
  }
}

test.describe('Пользователи бизнеса — открытая вкладка после смены роли/блокировки (#f6e816402bc7433839ec2a6f)', () => {
  test.skip(!HAS_SPARE, 'нет .qa/auth/spare.json — нужен расходный участник бизнеса с ролью מנהל/ת חשבון');

  test('понижение → меню и метка «מנהל/ת מגייס/ת» после перехода без F5; повышение → меню полное @desktop @data #f6e816402bc7433839ec2a6f', async ({ asUser }) => {
    const business = await asUser('business');
    const spare = await asUser('spare');

    await openUsers(business);
    try {
      await setManager(business); // исходное состояние — מנהל/ת חשבון

      // Жертва открыта на /settings/users как מנהל/ת חשבון.
      await spare.goto('/settings/users');
      for (const name of MANAGER_ONLY_LINKS) await expect(spare.getByRole('link', { name })).toBeVisible();
      await expect(spare.getByText(MANAGER, { exact: true }).first()).toBeVisible();

      // business понижает.
      const row = spareRow(business);
      await row.getByRole('button', { name: `הפיכה ל${RECRUITER}` }).click();
      await expect(row).toContainText(RECRUITER);
      await expect(row.getByRole('button', { name: `הפיכה ל${MANAGER}` })).toBeVisible();

      // Жертва без F5 переходит по меню. Источник: «מה רצוי» «הממשק מתעדכן להרשאה החדשה במעבר מסך…».
      await spare.getByRole('link', { name: 'סימולציות' }).click();
      await spare.waitForURL(/\/simulations/);
      for (const name of MANAGER_ONLY_LINKS) await expect(spare.getByRole('link', { name })).toHaveCount(0);
      await expect(spare.getByText(RECRUITER, { exact: true }).first()).toBeVisible();

      // business повышает обратно; жертва переходит — меню полное.
      await row.getByRole('button', { name: `הפיכה ל${MANAGER}` }).click();
      await expect(row.getByRole('button', { name: `הפיכה ל${RECRUITER}` })).toBeVisible();
      await spare.getByRole('link', { name: 'מועמדים' }).click();
      await spare.waitForURL(/\/candidates/);
      for (const name of MANAGER_ONLY_LINKS) await expect(spare.getByRole('link', { name })).toBeVisible();
      await expect(spare.getByText(MANAGER, { exact: true }).first()).toBeVisible();
    } finally {
      await openUsers(business);
      await setManager(business);
    }
  });

  test('блокировка → при переходе /login?notice=blocked, данных нет, «назад» → вход, без циклов 401/403; старый токен — 200 [] @desktop @data #f6e816402bc7433839ec2a6f #4cfd0ae49bece5d24e46d903', async ({ asUser }) => {
    test.skip(!process.env.QA_RUN_SESSION_KILL, 'завершает сессию spare — запуск только с QA_RUN_SESSION_KILL=1, затем qa-login spare');
    const business = await asUser('business');
    const spare = await asUser('spare');

    await openUsers(business);
    const row = spareRow(business);
    try {
      await setManager(business);

      // Жертва открыта на /settings/users; запоминаем её токен.
      const spareApi = await openWithApi(spare, '/settings/users');
      const denied: number[] = [];
      spare.on('response', (r) => {
        if (r.status() === 401 || r.status() === 403) denied.push(r.status());
      });

      // business блокирует (подтверждение — если приложение его спрашивает).
      await row.getByRole('button', { name: 'חסימה', exact: true }).click();
      const confirm = business.getByRole('dialog').getByRole('button', { name: /חסימה|אישור/ });
      const unblock = row.getByRole('button', { name: 'ביטול חסימה' });
      await expect(unblock.or(confirm)).toBeVisible();
      if (await confirm.isVisible()) await confirm.click();
      await expect(unblock).toBeVisible();

      // Старый токен заблокированного участника — данных нет (UA-002; «מה רצוי» #4cfd0ae4).
      for (const table of DATA_TABLES) {
        const res = await spareApi.get(`${table}?select=id&limit=3`);
        expect(res.status(), `${table}: статус`).toBe(200);
        expect(await res.json(), `${table}: заблокированный не должен читать данные`).toEqual([]);
      }

      // Жертва без F5 переходит по меню → выход. Источник: «מה רצוי» «ומשתמש חסום מנותק»; F-07 AC.
      await spare.getByRole('link', { name: 'מועמדים' }).click();
      await spare.waitForURL(/\/login\?notice=blocked/);
      await expect(spare.getByText('הגישה לחשבון חסומה')).toBeVisible();
      await expect(spare.getByText('יש לפנות לתמיכה או למנהל/ת החשבון בעסק')).toBeVisible();
      await expect(spare.getByRole('link', { name: 'משתמשים והזמנות' })).toHaveCount(0);

      // «Назад» — снова вход, без данных.
      await spare.goBack();
      await expect(spare).toHaveURL(/\/login/);
      await expect(spare.getByRole('button', { name: 'התחברות' })).toBeVisible();

      // Без циклов отказов: была одна 403 и выход (допуск — 2).
      expect(denied.length, `ответы 401/403 после блокировки: ${denied.join(',')}`).toBeLessThanOrEqual(2);
    } finally {
      await openUsers(business);
      const unblock = spareRow(business).getByRole('button', { name: 'ביטול חסימה' });
      if (await unblock.isVisible()) {
        await unblock.click();
        const confirm = business.getByRole('dialog').getByRole('button', { name: /ביטול חסימה|אישור/ });
        if (await confirm.isVisible()) await confirm.click();
        await expect(spareRow(business).getByRole('button', { name: 'חסימה', exact: true })).toBeVisible();
      }
    }
  });
});
